contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We take an input indicating a withdrawAll call attempt by this contract.
    // The test contract is NOT the owner by default (owner is deployer of C), so this checks the revert behavior and state invariants.
    function run(bool callAsOwner) public payable {
        // read before-values
        address beforeOwner = c.owner(); if (__ESBMC_reverted()) return;
        uint beforeDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint beforeBalance = address(c).balance;

        bool reverted;
        // Make the state-changing call as top-level statement. We cannot change msg.sender in this test,
        // so this call will succeed only if this contract is the owner (which can happen if the checker deploys C with this contract as deployer).
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // read after-values
        address afterOwner = c.owner(); if (__ESBMC_reverted()) return;
        uint afterDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint afterBalance = address(c).balance;

        // General rule: withdrawAll cannot change depositsCount, and C's balance does not increase (i.e., afterBalance <= beforeBalance).
        // Also owner is unchanged.
        assert(afterOwner == beforeOwner && afterDeposits == beforeDeposits && afterBalance <= beforeBalance);
    }

    receive() external payable {}
}

